import React from 'react';

import styles from '../../css/Searchprod.module.css'

const SingleCategory = () => {
  return (
    <div className='container'>
      <div className={styles.searchprod}>
        
        <div className={styles.search_field}>
          <input type="text" className={styles.search_input + ' ' + styles.prodname} placeholder='Product name' />
          <input type="text" className={styles.search_input + ' ' + styles.priceprod} placeholder='Price from' />
        </div>
      </div>
    </div>
  );
}

export default SingleCategory;
